R,C=len(grid),len(grid[0]); seen=set(); stack=[]
for r in range(R):
 for c in range(C):
  if r in (0,R-1) or c in (0,C-1):
   if grid[r][c]==7 and (r,c) not in seen: seen.add((r,c));stack.append((r,c))
while stack:
 r,c=stack.pop()
 for nr,nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
  if 0<=nr<R and 0<=nc<C and grid[nr][nc]==7 and (nr,nc) not in seen:
   seen.add((nr,nc));stack.append((nr,nc))
for r in range(R):
 for c in range(C):
  if grid[r][c]==7 and (r,c) not in seen:grid[r][c]=4
print(grid)
print('filled',[(r,c) for r in range(R) for c in range(C) if grid[r][c]==4])
